import {Component, Inject, Input} from '@angular/core';
import {ClientTicketWidgetMessage} from '@/lora-client/src/types/ClientWidgetMessage';
import {NgForOf} from "@angular/common";
import {ClientMessage} from "@/lora-client/src";

@Component({
  selector: 'lib-ticket-widget',
  standalone: true,
  imports: [NgForOf],
  styleUrl: './ticket-widget.component.scss',
  template: `
    <div class="ticket-widget">
      <div class="ticket-widget__header">Ticket information:</div>

      <table>
        <tr *ngFor="let field of fields">
          <td class="ticket-widget__field">{{ field.value }}:</td>
          <td>{{ getFieldValue(field.key) }}</td>
        </tr>
      </table>
    </div>
  `
})
export class TicketWidgetComponent {
  readonly fields = [{key: 'title', value: 'Title'}, {key: 'description', value: 'Description'}];

  constructor(@Inject('message') public message: ClientMessage) {
  }

  getFieldValue(key: string): string {
    console.log(this.message, key);
    //@ts-ignore
    return this.message?.widget?.widgetProps?.[key] || 'NO VALUE';
  }
}
